// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Start by transferring ownership to caller
        address currentOwner = c.owner();
        // Simulate that the current owner does transferOwnership
        vm.prank(currentOwner);
        c.transferOwnership(caller);
        // Then the caller accepts ownership
        vm.prank(caller);
        c.acceptOwnership();
        // The owner should now be the caller
        assertTrue(c.owner() == caller);
    }
}

